def transforms(mask):
 pts=set(mask); res=[]
 for refl in range(2):
  for rot in range(4):
   q=[(r, -c if refl else c) for r,c in pts]
   for _ in range(rot): q=[(c,-r) for r,c in q]
   minr=min(r for r,c in q); minc=min(c for r,c in q)
   q=tuple(sorted((r-minr,c-minc) for r,c in q))
   if q not in res:res.append(q)
 return res
